pub enum Msg {
    Ping,
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    let error = "unknown".to_string();
    eprintln!("decode error: {error}");
    Err(error)
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn roundtrip(msg: &Msg) -> Result<Msg, String> {
        decode(&encode(msg))
    }

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(roundtrip(&Msg::Ping), Ok(Msg::Ping)));
    }
}
